CREATE TABLE t1(a); INSERT INTO t1 VALUES ('x');
  CREATE VIEW t2(b) AS SELECT json(TRUE);
  CREATE TABLE t3(b); INSERT INTO t3 VALUES(json(TRUE));

CREATE TABLE t0(c0);
  INSERT INTO t0 VALUES ('1');
  CREATE VIEW v0(c0) AS SELECT CASE WHEN 1 THEN json_patch('1', '1') END 
                        FROM t0 GROUP BY t0.c0;
  SELECT * FROM v0 WHERE json_quote(v0.c0) != '1';

WITH t400(id,j) AS (VALUES
    (1,'{a:{x:1,y:2},b:{x:3,y:4}}'),
    (2,'not json')
  )
  SELECT id, subtype(if(json_valid(j,6),j->'a')) FROM t400;

DROP INDEX IF EXISTS i1;
    CREATE INDEX i1 ON t1( (CASE WHEN json_valid(j, 6) THEN j->'a' ELSE j END) );
    SELECT id, subtype( (CASE WHEN json_valid(j, 6) THEN j->'a' ELSE j END) ) FROM t1 INDEXED BY i1 ORDER BY id;

DROP INDEX IF EXISTS i1;
    CREATE INDEX i1 ON t1( +(CASE WHEN json_valid(j, 6) THEN j->'a' ELSE j END) );
    SELECT id, subtype( +(CASE WHEN json_valid(j, 6) THEN j->'a' ELSE j END) ) FROM t1 INDEXED BY i1 ORDER BY id;

DROP INDEX IF EXISTS i1;
    CREATE INDEX i1 ON t1( -(CASE WHEN json_valid(j, 6) THEN j->'a' ELSE j END) );
    SELECT id, subtype( -(CASE WHEN json_valid(j, 6) THEN j->'a' ELSE j END) ) FROM t1 INDEXED BY i1 ORDER BY id;

DROP INDEX IF EXISTS i1;
    CREATE INDEX i1 ON t1( if( json_valid(j, 6), j->'a' )  );
    SELECT id, subtype( if( json_valid(j, 6), j->'a' )  ) FROM t1 INDEXED BY i1 ORDER BY id;

DROP INDEX IF EXISTS i1;
    CREATE INDEX i1 ON t1( if( json_valid(j, 6), j->'a' ) COLLATE nocase );
    SELECT id, subtype( if( json_valid(j, 6), j->'a' ) COLLATE nocase ) FROM t1 INDEXED BY i1 ORDER BY id;

DROP INDEX IF EXISTS i1;
    CREATE INDEX i1 ON t1( CAST( if( json_valid(j, 6), j->'a' ) AS TEXT ) );
    SELECT id, subtype( CAST( if( json_valid(j, 6), j->'a' ) AS TEXT ) ) FROM t1 INDEXED BY i1 ORDER BY id;
